Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='wordsowed', at=datetime(2026, 10, 9, 0, 0, 0), actor='assistant', title='The inbox and the bookkeeping files still push words, and are owed the same locking', body="The inbox store, state.json, requests and briefings are still pushed with words in the clear. They are the next to stop pushing words, by the same means as the conversations: a new store with locked words, or a file that stays on the box and is vaulted. The merge gate's guard lists them as pending, so a new pushed store cannot go unclassified, and the pending list is empty when the last one moves.", rationale='The owner chose on 2026-10-09 to fix forward, so that in the end no pushed store holds words.', supersedes=()))